import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public static final class SliceBook<T> {
        private final List<T> items;
        private final int sliceSize;

        public SliceBook(List<? extends T> source, int sliceSize) {
            if (source == null || sliceSize <= 0) {
                throw new IllegalArgumentException("Invalid arguments");
            }
            ArrayList<T> copy = new ArrayList<T>(source.size());
            for (T item : source) {
                if (item == null) throw new IllegalArgumentException("Null item");
                copy.add(item);
            }
            this.items = copy;
            this.sliceSize = sliceSize;
        }

        public int itemCount() {
            return items.size();
        }

        public int sliceCount() {
            int size = items.size();
            return size == 0 ? 0 : size / sliceSize;
        }

        public int sizeOfSlice(int sliceIndex) {
            if (sliceIndex < 0 || sliceIndex >= sliceCount()) return -1;
            int start = sliceIndex * sliceSize;
            return Math.min(sliceSize, items.size() - start);
        }

        public int sliceOfItem(int itemIndex) {
            if (itemIndex < 0 || itemIndex >= items.size()) return -1;
            return itemIndex / sliceSize;
        }

        public List<T> slice(int sliceIndex) {
            int count = sizeOfSlice(sliceIndex);
            if (count < 0) return Collections.emptyList();
            int start = sliceIndex * sliceSize;
            return Collections.unmodifiableList(
                    new ArrayList<T>(items.subList(start, start + count)));
        }
    }
}

