import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        ArrayList<String> source = new ArrayList<String>(Arrays.asList("a", "b", "c", "d", "e"));
        Solution.SliceBook<String> book = new Solution.SliceBook<String>(source, 2);
        eq(5, book.itemCount());
        eq(3, book.sliceCount());
        eq(2, book.sizeOfSlice(0));
        eq(2, book.sizeOfSlice(1));
        eq(1, book.sizeOfSlice(2));
        eq(-1, book.sizeOfSlice(-1));
        eq(-1, book.sizeOfSlice(3));
        eq(0, book.sliceOfItem(0));
        eq(1, book.sliceOfItem(2));
        eq(2, book.sliceOfItem(4));
        eq(-1, book.sliceOfItem(-1));
        eq(-1, book.sliceOfItem(5));
        eq(Arrays.asList("c", "d"), book.slice(1));

        List<String> first = book.slice(0);
        List<String> firstAgain = book.slice(0);
        check(first != firstAgain);
        unmodifiable(first);
        List<String> invalid = book.slice(99);
        check(invalid.isEmpty());
        unmodifiable(invalid);

        source.set(0, "changed");
        source.remove(4);
        source.add("new");
        eq(Arrays.asList("a", "b"), book.slice(0));
        eq(Arrays.asList("e"), book.slice(2));

        Solution.SliceBook<String> empty = new Solution.SliceBook<String>(Collections.<String>emptyList(), 3);
        eq(0, empty.itemCount());
        eq(0, empty.sliceCount());
        eq(-1, empty.sizeOfSlice(0));
        eq(-1, empty.sliceOfItem(0));
        check(empty.slice(0).isEmpty());

        Solution.SliceBook<Integer> overflowBoundary = new Solution.SliceBook<Integer>(Arrays.asList(1, 2), Integer.MAX_VALUE);
        eq(1, overflowBoundary.sliceCount());
        eq(2, overflowBoundary.sizeOfSlice(0));

        bad(() -> new Solution.SliceBook<String>(null, 1));
        bad(() -> new Solution.SliceBook<String>(Arrays.asList("x", null), 1));
        bad(() -> new Solution.SliceBook<String>(Collections.singletonList("x"), 0));
        bad(() -> new Solution.SliceBook<String>(Collections.singletonList("x"), -1));
    }

    private static void unmodifiable(List<String> list) { try { list.add("x"); throw new AssertionError("modifiable"); } catch (UnsupportedOperationException expected) {} }
    private static void check(boolean value) { if (!value) throw new AssertionError(); }
    private static void eq(Object expected, Object actual) { if (!java.util.Objects.equals(expected, actual)) throw new AssertionError("expected=" + expected + ", actual=" + actual); }
    private static void bad(Runnable action) { try { action.run(); throw new AssertionError("expected IllegalArgumentException"); } catch (IllegalArgumentException expected) {} }
}

